<?php
return ['options'=>['tolerance'],'call'=>function($input,$options,&$state){
 if(!is_array($input)||array_diff(array_keys($input),['matrix','rhs']))throw new InvalidArgumentException('linear-system requires matrix and rhs');$a=$input['matrix']??NULL;$b=$input['rhs']??NULL;if(!is_array($a)||!array_is_list($a)||count($a)<1||count($a)>128||!is_array($b)||!array_is_list($b)||count($b)!==count($a))throw new InvalidArgumentException('dense system requires 1..128 square rows and matching rhs');$n=count($a);$tol=padNumericTolerance($options);$scale=[];
 foreach($a as $i=>$row){if(!is_array($row)||!array_is_list($row)||count($row)!==$n)throw new InvalidArgumentException('matrix must be square');foreach($row as $j=>$v){padNumericTick($state);$a[$i][$j]=padNumericFinite($v,'matrix entry');}$b[$i]=padNumericFinite($b[$i],'rhs');$scale[$i]=max(array_map('abs',$a[$i]));}$original=$a;$rhs=$b;$minPivot=1.0;
 $fail=fn($status,$iterations)=>['status'=>$status,'value'=>NULL,'iterations'=>$iterations,'tolerance'=>$tol,'residual'=>NULL,'relativeResidual'=>NULL];
 for($k=0;$k<$n;$k++){$pivot=$k;$best=-1.0;for($i=$k;$i<$n;$i++){$ratio=$scale[$i]==0?0:abs($a[$i][$k])/$scale[$i];if($ratio>$best){$best=$ratio;$pivot=$i;}}if($best==0)return $fail('singular',$k);if($best<=$tol)return $fail('ill-conditioned',$k);$minPivot=min($minPivot,$best);if($pivot!==$k){[$a[$k],$a[$pivot]]=[$a[$pivot],$a[$k]];[$b[$k],$b[$pivot]]=[$b[$pivot],$b[$k]];[$scale[$k],$scale[$pivot]]=[$scale[$pivot],$scale[$k]];}
 for($i=$k+1;$i<$n;$i++){$factor=$a[$i][$k]/$a[$k][$k];$a[$i][$k]=0;for($j=$k+1;$j<$n;$j++){padNumericTick($state);$a[$i][$j]=padNumericFinite($a[$i][$j]-$factor*$a[$k][$j],'elimination result');}$b[$i]=padNumericFinite($b[$i]-$factor*$b[$k],'rhs elimination');}}
 $x=array_fill(0,$n,0.0);for($i=$n-1;$i>=0;$i--){$sum=$b[$i];for($j=$i+1;$j<$n;$j++){padNumericTick($state);$sum=padNumericFinite($sum-$a[$i][$j]*$x[$j],'back substitution');}$x[$i]=padNumericFinite($sum/$a[$i][$i],'solution');}
 $residual=0.0;$normA=0.0;for($i=0;$i<$n;$i++){$sum=0.0;$c=0.0;$rowNorm=0.0;for($j=0;$j<$n;$j++){padNumericTick($state);$term=padNumericFinite($original[$i][$j]*$x[$j],'residual product')-$c;$next=padNumericFinite($sum+$term,'residual sum');$c=($next-$sum)-$term;$sum=$next;$rowNorm=padNumericFinite($rowNorm+abs($original[$i][$j]),'matrix norm');}$residual=max($residual,abs(padNumericFinite($sum-$rhs[$i],'residual')));$normA=max($normA,$rowNorm);}$normX=max(array_map('abs',$x));$normB=max(array_map('abs',$rhs));$den=padNumericFinite($normA*$normX+$normB,'residual denominator');$relative=$den==0?0:$residual/$den;
 return ['status'=>$relative<=$tol?'ok':'not-converged','method'=>'Gaussian elimination with scaled partial pivoting','value'=>$x,'iterations'=>$n,'tolerance'=>$tol,'residual'=>$residual,'relativeResidual'=>$relative,'minimumScaledPivot'=>$minPivot];
}];
